// features/meals/model/useMeals.js
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import {
  fetchMealsApi,
  addMealApi,
  deleteMealApi,
} from "../../api/mealsApi";

/**
 * Хук для работы с едой пользователя
 * @param {string} date - дата в формате YYYY-MM-DD
 * @param {string} token - токен авторизации
 */
export const useMeals = (date, token) => {
  const queryClient = useQueryClient();

  // =============================
  // GET MEALS
  // =============================
  const { data: rows = [], isLoading: loading } = useQuery({
    queryKey: ["meals", date],
    queryFn: () => fetchMealsApi(token, date),
    enabled: !!token
  });

  // =============================
  // ADD MEAL
  // =============================
  const addMealMutation = useMutation({
    mutationFn: ({ mealId, amount }) => addMealApi(token, mealId, amount),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: ["meals", date] })
  });

  // =============================
  // DELETE MEAL
  // =============================
  const deleteMealMutation = useMutation({
    mutationFn: (mealId) => deleteMealApi(token, mealId),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: ["meals", date] })
  });

  // =============================
  // HANDLERS (для UI)
  // =============================
  const handleAddMeal = (mealId, amount) => addMealMutation.mutate({ mealId, amount });
  const handleDeleteMeal = (mealId) => deleteMealMutation.mutate(mealId);

  return { rows, loading, handleAddMeal, handleDeleteMeal };
};
